x.append(R(6447164,"शिमला मिर्च पॉपर्स","इन पॉपर्स में थोड़ा और तीखापन चाहिए तो अपनी पसंद के अनुसार कुटी लाल मिर्च के फ्लेक्स की मात्रा बढ़ा लें।","12","2 पॉपर",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","12 छोटी मिनी मीठी मिर्चें","2 स्लाइस टर्की बेकन (छोटे टुकड़ों में कटा हुआ)","1/2 कप प्याज (छोटे टुकड़ों में कटा हुआ)","4 औंस फैट-फ्री क्रीम चीज़ (कमरे के तापमान पर)","2 औंस मुलायम बकरी का चीज़ (कमरे के तापमान पर)","1/4 छोटा चम्मच कुटी लाल मिर्च के फ्लेक्स","1 स्लाइस होल व्हीट ब्रेड (टोस्ट की हुई)","1 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच परमेसन चीज़ (कद्दूकस किया हुआ)"],
["ओवन को पहले से 375° F पर गरम करें। बेकिंग शीट पर कुकिंग स्प्रे लगा लें। एक तरफ रख दें।","हर मिर्च को लंबाई में आधा काटें, फिर बीज और अंदर की झिल्ली निकाल दें।","एक नॉन-स्टिक सॉते पैन में कुकिंग स्प्रे लगाकर बेकन डालें और मध्यम आंच पर कुरकुरा होने तक पकाएँ। पेपर टॉवल पर निकालकर तेल सोख लें और एक तरफ रख दें।","बेकन पकाने वाले पैन में प्याज डालें, ज़रूरत हो तो और कुकिंग स्प्रे लगाएँ। प्याज को बीच-बीच में चलाते हुए पारदर्शी होने तक पकाएँ। ठंडा होने के लिए एक तरफ रख दें।","एक छोटे कटोरे में क्रीम चीज़ और बकरी का चीज़ मिलाएँ। इसमें बेकन, प्याज और कुटी लाल मिर्च के फ्लेक्स डालें। सबको अच्छी तरह मिला लें।","टोस्ट की हुई ब्रेड को लहसुन और परमेसन चीज़ के साथ फ़ूड प्रोसेसर में पीस लें। इसे एक छोटे कटोरे में अलग रख दें।","चीज़ का मिश्रण हर मिर्च के आधे हिस्से में भरें (हर पॉपर के लिए 1 छोटा चम्मच मिश्रण), फिर पॉपर के चीज़ वाले हिस्से को होल व्हीट ब्रेड के चूरे के मिश्रण में दबाएँ। इन्हें तैयार बेकिंग शीट पर ब्रेड के चूरे वाला हिस्सा ऊपर रखकर लगाएँ और हर एक पर हल्के से कुकिंग स्प्रे करें।","पॉपर्स को लगभग 20 मिनट तक या मिर्चें नरम होने और ब्रेड का चूरा सुनहरा भूरा होने तक बेक करें।"]))
x.append(R(6448197,"प्याज, पालक और आर्टिचोक डिप","इस डिप को बेबी गाजर, अजवाइन की डंडियों, कटे हुए खीरे या मिनी शिमला मिर्च जैसी ताज़ा कटी सब्ज़ियों के साथ खाएँ। अपनी अगली पार्टी की थाली में ज़्यादा सब्ज़ियाँ (और इसलिए ज़्यादा पोषक तत्व) शामिल करने का यह एक आसान तरीका है!","20","2 बड़े चम्मच",
["1 छोटा चम्मच ऑलिव ऑयल","1 मध्यम प्याज (बारीक कटा हुआ)","1 (15 औंस) कैन आर्टिचोक हार्ट्स (पानी निथारकर धोए हुए)","1/2 छोटा चम्मच सूखा थाइम","6 औंस पालक (ताज़ा, मोटा कटा हुआ)","1/4 कप लाइट मेयोनेज़","4 वेज लाइट स्प्रेडेबल चीज़ वेज (जैसे लाफिंग काउ)","2 बड़े चम्मच परमेसन चीज़ (ताज़ा कद्दूकस किया हुआ, बाँटकर उपयोग के लिए)","2 बड़े चम्मच नींबू का रस (1 मध्यम नींबू से)"],
["ओवन को पहले से 350°F पर गरम करें।","एक बड़ी कड़ाही में मध्यम आंच पर ऑलिव ऑयल गरम करें। प्याज डालें और बार-बार चलाते हुए 5 मिनट तक भूनें। आर्टिचोक और थाइम डालें और 3 मिनट और पकाएँ, जब तक सब्ज़ियाँ भूरी होने न लगें। पालक डालें और 1-2 मिनट और पकाएँ, जब तक पालक मुरझा न जाए। कड़ाही को आंच से उतार लें।","माइक्रोवेव में रखने योग्य कटोरे में लाइट मेयोनेज़, चीज़ वेज और 1 बड़ा चम्मच परमेसन चीज़ मिलाएँ। इसे माइक्रोवेव में 30 सेकंड गरम करके नरम करें, फिर अच्छी तरह मिलाएँ। ज़रूरत हो तो मिश्रण को 15-15 सेकंड करके तब तक गरम करें जब तक चीज़ नरम होकर मेयोनेज़ में आसानी से न मिल जाए।","चीज़ के मिश्रण और नींबू के रस को भुनी हुई सब्ज़ियों में डालकर अच्छी तरह मिलाएँ। डिप को एक छोटे बेकिंग डिश में फैलाएँ, ऊपर से बचा हुआ 1 बड़ा चम्मच परमेसन चीज़ डालें और ओवन में 5 मिनट बेक करें। गरमागरम परोसें।"]))
x.append(R(6450804,"श्रिम्प फजीटा","इस व्यंजन को जिकामा की डंडियों और ताज़ा गुआकामोले के साथ परोसें। चाहें तो अलग-अलग रंगों की शिमला मिर्च या बैंगनी प्याज़ का उपयोग करके इस रंग-बिरंगे व्यंजन को और भी आकर्षक बना सकते हैं।","5","2 फजीटा",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 पाउंड झींगा (मध्यम आकार, छिला और नस निकाला हुआ)","1 छोटा चम्मच ऑलिव ऑयल","1 मध्यम लाल शिमला मिर्च (पतली कटी हुई)","1 मध्यम हरी शिमला मिर्च (पतली कटी हुई)","1 मध्यम प्याज (पतला कटा हुआ)","1/4 कप पानी","1/2 बड़ा चम्मच चिली पाउडर","1/4 छोटा चम्मच लाल मिर्च पाउडर (वैकल्पिक)","1/4 छोटा चम्मच जीरा","1/2 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च","10 छोटे मक्के के टॉर्टिला"],
["एक बड़ी नॉन-स्टिक कड़ाही में कुकिंग स्प्रे लगाएँ। झींगे को मध्यम आंच पर लगभग 2 मिनट पकाएँ। झींगे को पैन से निकालकर एक तरफ रख दें।","पैन में तेल डालकर गरम करें। शिमला मिर्च और प्याज डालें और लगभग 7 मिनट या भूरा होने तक पकाएँ। झींगे को उनके रस सहित वापस पैन में डालें।","पानी और मसाले, नमक और काली मिर्च सहित, डालें। मिश्रण में उबाल आने दें; आंच कम करें और पानी सूखने तक पकाएँ। झींगे और शिमला मिर्च को मक्के के टॉर्टिला में रखकर परोसें।"]))
x.append(R(6451442,"टोफू और सब्ज़ियों की सींख, ब्राउन राइस के साथ","एक सेहतमंद रात के खाने के लिए ग्रिल जलाएँ और टोफू व सब्ज़ियों की सींख बनाएँ। एशियाई अंदाज़ की स्वादिष्ट मैरिनेड इस मधुमेह के अनुकूल भोजन में भरपूर स्वाद भर देती है।","4","2 सींख + 1/3 कप पका हुआ ब्राउन राइस",
["2 बड़े चम्मच कम सोडियम वाली सोया सॉस","2 बड़े चम्मच राइस विनेगर","1 बड़ा चम्मच तिल का तेल","1 बड़ा चम्मच मेपल सिरप","2 कली लहसुन (बारीक कटी हुई)","1 छोटा चम्मच ताज़ा अदरक (कद्दूकस किया हुआ)","16 औंस सख़्त टोफू (दबाकर पानी निकाला हुआ और टुकड़ों में कटा हुआ)","1 मध्यम लाल प्याज (बड़े टुकड़ों में कटा हुआ)","2 साबुत शिमला मिर्च (बड़े टुकड़ों में कटी हुई)","2 मध्यम पीली स्क्वैश (गोल स्लाइस में कटी हुई)","1 1/3 कप पका हुआ ब्राउन राइस"],
["एक कटोरे में सोया सॉस, राइस विनेगर, तिल का तेल, मेपल सिरप या एगेव नेक्टर, बारीक कटा लहसुन और कद्दूकस किया अदरक फेंटकर मैरिनेड तैयार करें।","दबाकर पानी निकाले हुए टोफू को टुकड़ों में काटकर एक उथले डिश में रखें। आधा मैरिनेड टोफू पर डालें और ध्यान रखें कि हर टुकड़े पर लग जाए। इसे कम से कम 30 मिनट मैरिनेट होने दें।","टोफू के मैरिनेट होने के दौरान सब्ज़ियाँ तैयार करें। मैरिनेट किया हुआ टोफू, लाल प्याज के टुकड़े, शिमला मिर्च के टुकड़े और पीली स्क्वैश के गोल स्लाइस बारी-बारी से सींखों में पिरोएँ।","ग्रिल या ग्रिल पैन को मध्यम-तेज़ आंच पर पहले से गरम करें।","सींखों को लगभग 10–15 मिनट तक बीच-बीच में पलटते हुए ग्रिल करें, जब तक टोफू सुनहरा और सब्ज़ियाँ हल्की जली और नरम न हो जाएँ। अतिरिक्त स्वाद के लिए ग्रिल करते समय बचा हुआ मैरिनेड सींखों पर लगाते रहें।","पक जाने पर सींखों को ग्रिल से उतारें और परोसने से पहले कुछ मिनट रखा रहने दें।","पके हुए ब्राउन राइस के साथ परोसें, प्रति सर्विंग 1/3 कप।"]))
x.append(R(6451648,"धनिया-नींबू क्विनोआ","क्विनोआ में किसी भी अन्य अनाज से ज़्यादा प्रोटीन होता है। यह ग्लूटेन-मुक्त है, प्रति सर्विंग 2 ग्राम फाइबर देता है, और चावल वाली किसी भी रेसिपी का सेहतमंद विकल्प है।","6","1/2 कप",
["1 बड़ा चम्मच कैनोला तेल","1 छोटा प्याज (कटा हुआ)","2 कली लहसुन (बारीक कटी हुई)","1 कप क्विनोआ (सूखा)","2 कप कम सोडियम वेजिटेबल ब्रॉथ (फैट-फ्री, (ज़रूरत हो तो ग्लूटेन-मुक्त))","4 बड़े चम्मच ताज़ा नींबू का रस (2 मध्यम नींबू से)","1/2 कप ताज़ा धनिया (कटा हुआ)"],
["एक बड़ी कड़ाही में मध्यम आंच पर तेल गरम करें। प्याज डालें और 3 से 4 मिनट पकाएँ। लहसुन डालें और 30 सेकंड पकाएँ। आंच धीमी करें और क्विनोआ डालें। धीमी आंच पर 1-2 मिनट लगातार चलाते हुए पकाएँ ताकि क्विनोआ जले नहीं।","वेजिटेबल ब्रॉथ और 1 नींबू का रस डालें और उबाल आने दें। आंच धीमी करें, ढककर 15 मिनट या पकने तक पकाएँ। आंच से उतार लें।","1 नींबू का रस और कटा हुआ धनिया मिलाएँ।"]))
x.append(R(6452003,"फिली चीज़स्टेक स्टफ्ड शिमला मिर्च","इन फिली चीज़स्टेक स्टफ्ड शिमला मिर्चों में मूल व्यंजन के सारे चटपटे स्वाद हैं, लेकिन रोल के बिना। ब्रेड की जगह शिमला मिर्च लेने से कार्बोहाइड्रेट कम होते हैं और फाइबर व पोषक तत्व बढ़ते हैं। यह कम कार्ब वाला बेहतरीन रात का खाना है जो ब्लड ग्लूकोज (रक्त शर्करा) को स्थिर रखने में मदद कर सकता है।","4","1 भरी हुई शिमला मिर्च",
["2 साबुत हरी शिमला मिर्च (लंबाई में आधी कटी हुई, बीज निकाले हुए)","1 छोटा चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल","1 बड़ा प्याज (आधा काटकर पतला कटा हुआ)","8 औंस क्रेमिनी (बेबी बेला) मशरूम (पतले कटे हुए)","12 औंस टॉप राउंड स्टेक (चर्बी हटाया हुआ, पतला कटा हुआ)","1 बड़ा चम्मच इटैलियन सीज़निंग","1/2 छोटा चम्मच काली मिर्च","1/4 छोटा चम्मच नमक","1 बड़ा चम्मच वॉरसेस्टरशायर सॉस","1/4 कप पार्ट-स्किम मोत्ज़ारेला (कद्दूकस किया हुआ)","2 डंठल हरा प्याज (स्प्रिंग अनियन) (कटा हुआ)"],
["ओवन को पहले से 375 डिग्री F पर गरम करें। शिमला मिर्च के आधे हिस्सों को कटे हुए भाग को ऊपर की ओर करके बेकिंग शीट पर रखें। लगभग 30 मिनट बेक करें, जब तक वे नरम हो जाएँ लेकिन अपना आकार बनाए रखने लायक सख़्त रहें।","जब तक मिर्चें ओवन में हैं, एक बड़ी कड़ाही में मध्यम आंच पर ऑलिव ऑयल गरम करें। कटा हुआ प्याज डालें और बीच-बीच में चलाते हुए लगभग 4–5 मिनट पकाएँ, जब तक वह नरम होकर भूरा न होने लगे।","मशरूम डालकर चलाएँ और 5 मिनट और पकाएँ ताकि वे अपना पानी छोड़ दें।","स्टेक के टुकड़ों को इटैलियन सीज़निंग, काली मिर्च और नमक के साथ पैन में डालें। बार-बार चलाते हुए 3–5 मिनट पकाएँ, जब तक स्टेक भूरा होकर अच्छी तरह पक न जाए।","वॉरसेस्टरशायर सॉस डालें, मिलाएँ और कड़ाही को आंच से उतार लें।","ओवन को ब्रॉइल पर कर दें।","हर शिमला मिर्च के आधे हिस्से में स्टेक का मिश्रण बराबर मात्रा में भरें और ऊपर से चीज़ छिड़कें।","मिर्चों को वापस ओवन में रखें और 2–3 मिनट ब्रॉइल करें, जब तक चीज़ पूरी तरह पिघलकर हल्की सुनहरी न हो जाए।","परोसते समय ऊपर से कटा हुआ हरा प्याज डालें।"]))
x.append(R(6452790,"नींबू सॉर्बे","यह कम कार्ब वाला नींबू सॉर्बे एक ताज़गी भरी, खट्टी-मीठी जमी हुई मिठाई है, जिसमें ज़्यादा चीनी और कैलोरी के बिना नींबू का भरपूर स्वाद मिलता है। मधुमेह के भोजन-योजना का पालन करते हुए अपनी मीठा खाने की इच्छा पूरी करने के लिए इसे ताज़गी भरे व्यंजन के रूप में खाएँ।","4","1/2 कप",
["4 नींबू का रस (निचोड़ा हुआ)","1/2 कप पानी","2 छोटे चम्मच लिक्विड स्टीविया स्वीटनर"],
["एक कटोरे में नींबू का रस, पानी और स्टीविया को फेंट लें।","आइसक्रीम मेकर में डालें और निर्माता के निर्देशों के अनुसार चलाएँ।","नरम सॉर्बे के लिए इसे तुरंत खाएँ। ज़्यादा ठोस बनावट के लिए इसे फ्रीज़र में रखने योग्य डिब्बे में डालकर 2 घंटे जमाएँ।"]))
x.append(R(6453245,"चटपटे सब्ज़ी अंडा मफिन","ये चटपटे सब्ज़ी अंडा मफिन फाइबर, प्रोटीन और रंग-बिरंगी सब्ज़ियों से भरपूर, झटपट उठाकर ले जाने वाला नाश्ता हैं। गेहूँ के आटे, कद्दूकस की हुई सब्ज़ियों और थोड़े से कम वसा वाले चीज़ के आधार पर बने ये मफिन भारी हुए बिना पेट भरते हैं। पोषक तत्वों का संतुलित मिश्रण इन्हें मधुमेह को नियंत्रित करने वालों के लिए बेहतरीन विकल्प बनाता है। यह DASH (डायटरी अप्रोच टू स्टॉप हाइपरटेंशन), शाकाहारी और कम वसा वाली रेसिपी है।","4","2 मफिन",
["2 बड़ी तोरई (कद्दूकस की हुई और निचोड़कर सुखाई हुई)","1 बड़ी गाजर (कद्दूकस की हुई)","1/4 कप लाल शिमला मिर्च (बारीक कटी हुई)","1/4 कप लाल प्याज (बारीक कटा हुआ)","2 बड़े अंडे","2 औंस लिक्विड एग व्हाइट","1/4 कप कम वसा वाला दूध","1/2 कप गेहूँ का आटा (होल व्हीट)","1/2 छोटा चम्मच बेकिंग पाउडर","1/4 छोटा चम्मच काली मिर्च","1/8 छोटा चम्मच स्मोक्ड पेपरिका","1/4 कप कम वसा वाला कद्दूकस किया चेडर चीज़"],
["ओवन को पहले से 375°F (190°C) पर गरम करें और मफिन टिन में 8 पेपर लाइनर लगाएँ या कपों को कुकिंग स्प्रे से हल्का चिकना कर लें।","तोरई और गाजर को कद्दूकस करें, फिर साफ़ तौलिये से उनकी अतिरिक्त नमी निचोड़ दें। लाल शिमला मिर्च और लाल प्याज को बारीक काटें और सारी सब्ज़ियाँ एक कटोरे में मिला लें।","एक मध्यम कटोरे में अंडे, एग व्हाइट और कम वसा वाले दूध को अच्छी तरह मिलने तक फेंटें।","दूसरे कटोरे में गेहूँ का आटा, बेकिंग पाउडर, काली मिर्च और स्मोक्ड पेपरिका मिलाएँ।","सूखी सामग्री को धीरे-धीरे गीली सामग्री में फोल्ड करें और बस मिलने तक हल्के से चलाएँ। कद्दूकस की हुई सब्ज़ियाँ और चेडर चीज़ बैटर में डालें और बराबर फैलने तक फोल्ड करें।","बैटर को तैयार किए गए 8 मफिन कपों में बराबर बाँट दें। हर कप को लगभग 3/4 भरें।","18–22 मिनट बेक करें, या जब तक मफिन के बीच में डाली गई टूथपिक साफ़ बाहर न आए।","मफिन को टिन में 5 मिनट ठंडा होने दें, फिर वायर रैक पर निकाल लें। गरम या कमरे के तापमान पर परोसें।"]))
x.append(R(6454224,"मेमने की चॉप्स, आलू और वसंत ऋतु की सब्ज़ियों के साथ","मेमना ईस्टर के मौसम के लिए बढ़िया है और साल के किसी भी अन्य समय के लिए एक खास व्यंजन। मेमने की लोइन चॉप्स कोमल, कम चर्बी वाला हिस्सा है जो ग्रिल पर आसानी से पक जाता है। जब आप रोज़ के चिकन और बीफ से ऊब जाएँ, तो इसे आज़माना अच्छा विकल्प है। इसे शतावरी और गाजर जैसी वसंत ऋतु की सब्ज़ियों के साथ परोसें।","4","1-2 मेमने की चॉप + 1 आलू, 5 शतावरी की डंडियाँ और 2 गाजर",
["1 बड़ा चम्मच + 2 छोटे चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल (बाँटकर उपयोग के लिए)","2 कली लहसुन (बारीक कटी हुई)","1/2 छोटा चम्मच कोशर नमक","1/4 छोटा चम्मच काली मिर्च","3 बड़े चम्मच ताज़ा रोज़मेरी (कटी हुई, बाँटकर उपयोग के लिए)","1 पाउंड कम चर्बी वाली मेमने की लोइन चॉप्स (चर्बी हटाई हुई)","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","4 छोटे लाल आलू (चार टुकड़ों में कटे हुए, छिलके सहित)","8 मध्यम गाजर (आधी कटी हुई)","1 गुच्छा शतावरी (लगभग 20 डंडियाँ, छँटी हुई)"],
["1 बड़ा चम्मच ऑलिव ऑयल, लहसुन, नमक, काली मिर्च और रोज़मेरी मिलाएँ। चॉप्स पर अच्छी तरह लगाएँ और रेफ्रिजरेटर में 2 घंटे मैरिनेट करें। ग्रिल करने से 30 मिनट पहले रेफ्रिजरेटर से निकाल लें।","ओवन को पहले से 450°F पर गरम करें। शीट पैन पर कुकिंग स्प्रे करें।","आलू को एक कटोरे में रखकर 1 छोटा चम्मच ऑलिव ऑयल और 2 बड़े चम्मच कटी रोज़मेरी के साथ मिलाएँ। इन्हें शीट पैन पर रखें और पहले से गरम ओवन के बीच में रखकर 10 मिनट भूनें।","उसी कटोरे में गाजर रखकर बचे हुए तेल और रोज़मेरी के साथ मिलाएँ। इन्हें शतावरी के साथ आलू में डालें और 10 मिनट और भूनें।","इस बीच ग्रिल को पहले से गरम करें और मेमने की चॉप्स सीधे ग्रिल पर रखें। 5 मिनट ग्रिल करें, फिर चॉप्स को पलटें और 3 – 5 मिनट और ग्रिल करें। इनका आंतरिक तापमान 135°F तक पहुँचना चाहिए।"]))
x.append(R(6454316,"हवाईयन कतरी हुई ब्रसल्स स्प्राउट्स","ब्रसल्स स्प्राउट्स को कतरने के कुछ तरीके हैं। एक तरीका हाथ से है, बस हर स्प्राउट का डंठल वाला सिरा काट दें ताकि वह कटिंग बोर्ड पर सपाट बैठे। फिर शेफ के चाकू से उसे बहुत पतले स्लाइस में काट लें। (सिरा काटने से वह इधर-उधर लुढ़कता नहीं।) दूसरा तरीका फ़ूड प्रोसेसर का उपयोग है। बस स्प्राउट्स को चूट में डालें और स्लाइसिंग अटैचमेंट को काम करने दें!","6","1/2 कप",
["16 औंस ताज़ा ब्रसल्स स्प्राउट्स","1 बड़ा चम्मच कैनोला तेल","1 बड़ा चम्मच ब्राउन शुगर","1/2 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1 (8 औंस) कैन अनानास के टुकड़े रस में (अच्छी तरह निथारे हुए)","1 बड़ा चम्मच मैकाडामिया नट्स (कटे हुए)"],
["ब्रसल्स स्प्राउट्स के तले का डंठल काट दें, फिर स्प्राउट्स को चाकू से बहुत पतले स्लाइस में काटें, या फ़ूड प्रोसेसर में स्लाइस करें।","एक बड़ी कड़ाही में मध्यम आंच पर तेल को गरम होने तक गरम करें। ब्रसल्स स्प्राउट्स को बीच-बीच में चलाते हुए 5 से 7 मिनट या भूरा होने तक भूनें। ज़्यादा कुरकुरे स्प्राउट्स के लिए कुछ मिनट और भूनें।","ब्राउन शुगर, नमक, काली मिर्च और अनानास डालकर मिलाएँ। 3 से 5 मिनट या गरम होने तक पकाएँ। ऊपर से मैकाडामिया नट्स छिड़कें और परोसें।"]))
x.append(R(6456214,"फूलगोभी राइस और बीन्स फजीटा बाउल","इस मधुमेह के अनुकूल और वीगन भोजन में बीन्स आपके खाने में स्वादिष्ट पादप-आधारित प्रोटीन जोड़ती हैं। फूलगोभी से चावल बनाना अतिरिक्त कार्ब जोड़े बिना आहार में ज़्यादा पोषक तत्व लाने का बढ़िया तरीका है। थोड़े अतिरिक्त चटपटेपन के लिए अपने बाउल के ऊपर ताज़ा धनिया या सालसा डालें।","4","1 बाउल",
["1 मध्यम फूलगोभी","2 बड़े चम्मच ऑलिव ऑयल","1 (15 औंस) कैन काली बीन्स (बिना नमक मिलाए, निथारी और धोई हुई)","1 मध्यम लाल शिमला मिर्च (पतली कटी हुई)","1 मध्यम पीली शिमला मिर्च (पतली कटी हुई)","1 मध्यम लाल प्याज (पतला कटा हुआ)","2 छोटे चम्मच पिसा जीरा","1 छोटा चम्मच स्मोक्ड पेपरिका","1/2 छोटा चम्मच चिली पाउडर","1/2 छोटा चम्मच कोशर नमक","1/2 छोटा चम्मच काली मिर्च","1 मध्यम नींबू (आधा कटा हुआ)","2 बड़े चम्मच ताज़ा धनिया (कटा हुआ, सजावट के लिए)"],
["फ़ूड प्रोसेसर में फूलगोभी को तब तक पल्स करें जब तक वह चावल जैसी न दिखने लगे। एक तरफ रख दें।","एक बड़ी कड़ाही में मध्यम आंच पर ऑलिव ऑयल गरम करें। कटी हुई शिमला मिर्च और लाल प्याज डालें। सब्ज़ियाँ नरम होने तक, लगभग 5–7 मिनट भूनें।","चावल जैसी कटी फूलगोभी कड़ाही में डालें। ऊपर से पिसा जीरा, स्मोक्ड पेपरिका, चिली पाउडर, कोशर नमक और काली मिर्च छिड़कें। अच्छी तरह मिलाएँ।","फूलगोभी के मिश्रण को बीच-बीच में चलाते हुए 8–10 मिनट और पकाएँ, जब तक फूलगोभी नरम न हो जाए।","काली बीन्स डालकर मिलाएँ और 3–5 मिनट और पकाएँ जब तक सब कुछ गरम न हो जाए।","मिश्रण पर नींबू का रस निचोड़ें और मिलाएँ।","फूलगोभी राइस और बीन्स फजीटा मिश्रण को बाउल में बाँट दें। तुरंत परोसें। चाहें तो ताज़े धनिये से सजाएँ।"]))
x.append(R(6456614,"किफ़ायती स्लो-कुकर चिकन और शकरकंद","खाना पकाने का समय नहीं है? रात के खाने के लिए यह स्लो-कुकर चिकन आज़माएँ। शकरकंद, डिजॉन सरसों और ब्राउन शुगर इसे अनोखा और स्वादिष्ट बनाते हैं। साथ में सादी भाप में पकी ब्रोकली और फूलगोभी परोसने से यह पूरा भोजन बन जाता है, जिसमें सक्रिय तैयारी का समय 15 मिनट से भी कम लगता है।","4","1 चिकन थाई, 2-3 शकरकंद के गोल टुकड़े और 1 कप ब्रोकली और फूलगोभी का मिश्रण",
["1 पाउंड बिना हड्डी और बिना त्वचा की चिकन थाई","1 मध्यम प्याज (कटा हुआ)","1 पाउंड शकरकंद (छिले हुए और बड़े गोल टुकड़ों में कटे हुए)","1 1/2 कप कम सोडियम चिकन ब्रॉथ","3 बड़े चम्मच कम कैलोरी वाला ब्राउन शुगर विकल्प","1/4 छोटा चम्मच सूखा थाइम","2 बड़े चम्मच डिजॉन सरसों","1 तेज पत्ता","4 कप ताज़ा या फ्रोज़न ब्रोकली और फूलगोभी के फूल (भाप में पके हुए)"],
["चिकन को स्लो कुकर में रखें। चिकन के ऊपर प्याज और शकरकंद डालें।","चिकन ब्रॉथ, ब्राउन शुगर मिश्रण, थाइम, सरसों और तेज पत्ता डालें। धीमी आंच पर 5-6 घंटे या चिकन पकने तक पकाएँ।","तेज पत्ता निकाल दें और ब्रोकली व फूलगोभी के साथ परोसें।"]))
x.append(R(6457517,"पालक और फेटा भरे मशरूम","पालक और फेटा भरे मशरूम एक स्वादिष्ट और चटपटा स्टार्टर हैं, जो मशरूम के मिट्टी जैसे स्वाद को मलाईदार और स्वादिष्ट भराई के साथ जोड़ते हैं। ये चटपटे निवाले पार्टियों, त्योहारों के जमावड़ों या टापस थाली में एक स्वादिष्ट जोड़ के रूप में बेहतरीन स्टार्टर हैं।","8","2 भरे हुए मशरूम",
["16 बड़े क्रेमिनी (बेबी बेला) मशरूम (साफ़ किए हुए और डंठल निकाले हुए)","1 बड़ा चम्मच ऑलिव ऑयल","4 कप पालक (कटा हुआ)","2 कली लहसुन (बारीक कटी हुई)","1/2 कप फेटा चीज़ (चूरा किया हुआ)","1/2 कप परमेसन चीज़ (कम वसा वाला, कद्दूकस किया हुआ)","2 बड़े चम्मच सादा नॉनफैट ग्रीक योगर्ट","1/8 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च"],
["ओवन को पहले से 375 डिग्री F पर गरम करें और बेकिंग शीट पर बेकिंग पेपर बिछा लें।","एक कड़ाही में मध्यम आंच पर 1 बड़ा चम्मच ऑलिव ऑयल गरम करें। बारीक कटा लहसुन और कटा हुआ पालक डालें, और 2–3 मिनट भूनें, जब तक पालक मुरझा न जाए और अतिरिक्त नमी सूख न जाए। कड़ाही को आंच से उतार लें।","एक मिक्सिंग बाउल में भुना हुआ पालक और लहसुन, चूरा किया फेटा चीज़, कद्दूकस किया परमेसन चीज़, सादा ग्रीक योगर्ट, नमक और काली मिर्च मिलाएँ। सुनिश्चित करें कि सभी सामग्री अच्छी तरह मिल गई हो।","साफ़ किए हुए मशरूम लें और हर टोपी में पालक और चीज़ का मिश्रण भरें, हल्के से दबाते हुए।","भरे हुए मशरूम को तैयार बेकिंग शीट पर सजाएँ। चाहें तो भूरा होने में मदद के लिए उन पर हल्का सा कुकिंग स्प्रे कर सकते हैं।","भरे हुए मशरूम को पहले से गरम ओवन में लगभग 15–20 मिनट या नरम होने तक बेक करें, जब तक भराई गरम होकर हल्की भूरी न हो जाए।"]))
x.append(R(6457837,"तरबूज़-नींबू स्लशी","शक्कर वाले पेयों का यह ताज़गी भरा विकल्प आज़माएँ! यह ताज़े तरबूज़ से बनता है जो बिना अतिरिक्त चीनी के हल्का मीठा स्वाद देता है, साथ में चटपटा नींबू और ठंडा पुदीना। गर्मी के दिन के लिए बिल्कुल सही!","4","6 औंस (लगभग 3/4 कप)",
["2 कप तरबूज़","2 कप बर्फ","1/4 कप (लगभग 2 नींबू से) नींबू का रस","2 बड़े चम्मच (सजावट के लिए और भी) ताज़े पुदीने के पत्ते"],
["तरबूज़, बर्फ, नींबू का रस और पुदीने को ब्लेंडर में स्लशी जैसी बनावट आने तक प्यूरी करें। गिलासों में डालें और चाहें तो पुदीने की टहनी से सजाएँ।"]))
x.append(R(6458377,"पालक फेटा टर्की बर्गर","ये पालक फेटा बर्गर सामान्य बीफ़ पैटी का ज़्यादा सेहतमंद विकल्प हैं। कम कार्ब वाले भोजन के लिए इन्हें सलाद के पत्तों पर परोसें, या अगर आपकी खान-पान योजना अनुमति दे तो साबुत अनाज के बन में। ये स्वादिष्ट बर्गर पूरे परिवार को ज़रूर पसंद आएँगे!","4","1 बर्गर",
["12 औंस फ्रोज़न पालक (पिघलाया हुआ)","8 औंस कम चर्बी वाला टर्की का कीमा","1/4 कप लाल प्याज (बारीक कटा हुआ)","2 कली लहसुन (बारीक कटी हुई)","1 साबुत अंडा (फेंटा हुआ)","2 बड़े चम्मच गेहूँ की ब्रेड का चूरा (होल व्हीट)","1/4 छोटा चम्मच काली मिर्च","2 बड़े चम्मच कम वसा वाला फेटा चीज़ (चूरा किया हुआ)","1 बड़ा चम्मच ऑलिव ऑयल (तलने के लिए)"],
["पिघले हुए पालक से अतिरिक्त पानी निचोड़ दें।","एक बड़े कटोरे में निचोड़ा हुआ पालक, टर्की का कीमा, लाल प्याज, लहसुन, फेंटा हुआ अंडा, ब्रेड का चूरा, फेटा और काली मिर्च मिलाएँ।","इसे 4 बराबर पैटी में आकार दें।","एक बड़ी कड़ाही में मध्यम आंच पर ऑलिव ऑयल गरम करें। पैटी को हर तरफ 4-5 मिनट पकाएँ, जब तक वे अच्छी तरह पक न जाएँ और गहरे सुनहरे भूरे न हो जाएँ।"]))
save(1,x)
